import { icon } from '../../core/icon.97bef2043ca4.mjs';
import { t } from '../../core/i18n.af618b3f9c2a.mjs';
const PRIORITY=Object.freeze({permission:0,approval:1,'failed-after-retry':2,'ready-to-review':3,'checks-changed':4});
const ACTION=Object.freeze({permission:'Review permission',approval:'Review plan','failed-after-retry':'Inspect failure','ready-to-review':'Review changes','checks-changed':'Review checks'});
export function buildReviewQueue(items=[]){return Object.freeze(items.filter(i=>i?.id&&PRIORITY[i.kind]!==undefined).map(i=>Object.freeze({...i,primaryAction:ACTION[i.kind]})).sort((a,b)=>PRIORITY[a.kind]-PRIORITY[b.kind]||Number(a.waitingSince??0)-Number(b.waitingSince??0)))}
const esc=(v)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function kindFrom(item){const s=String(item.status??'').toLowerCase();if(/permission/.test(s))return'permission';if(/approval|needs_input|awaiting/.test(s))return'approval';if(/fail|error|blocked/.test(s))return'failed-after-retry';if(/review|ship/.test(s))return'ready-to-review';return null}
export function createReviewController({api,language='en'}={}){let state={status:'loading',language,items:[],error:null};const snapshot=()=>structuredClone(state);return Object.freeze({snapshot,async load(){state.status='loading';const r=await Promise.allSettled([api.get('/api/missions'),api.get('/api/tasks'),api.get('/api/sovereign-kernel/snapshot')]);const missions=r[0].status==='fulfilled'?(Array.isArray(r[0].value)?r[0].value:r[0].value?.missions??[]):[];const tasks=r[1].status==='fulfilled'?(Array.isArray(r[1].value)?r[1].value:r[1].value?.tasks??[]):[];const kernel=r[2].status==='fulfilled'?r[2].value:{};const approvals=Array.isArray(kernel?.approvals)?kernel.approvals:[];const raw=[...approvals.map(x=>({...x,kind:'permission',id:x.id??x.leaseId,title:x.title??x.reason??'Permission request'})),...tasks.map(x=>({...x,kind:kindFrom(x),title:x.title??x.objective??x.id})),...missions.map(x=>({...x,kind:kindFrom(x),title:x.objective??x.title??x.id}))].filter(x=>x.kind);state={...state,status:'ready',items:buildReviewQueue(raw),error:r.every(x=>x.status==='rejected')?'Nolane runtime could not be reached.':null};return snapshot()}})}
export function renderReviewQueue(itemsOrState=[]){const state=Array.isArray(itemsOrState)?{items:itemsOrState,status:'ready',language:'en'}:itemsOrState;const lang=state.language??'en';const vi=lang==='vi';const queue=buildReviewQueue(state.items??[]);const counts={permission:queue.filter(x=>x.kind==='permission').length,approval:queue.filter(x=>x.kind==='approval').length,review:queue.filter(x=>x.kind==='ready-to-review').length,failed:queue.filter(x=>x.kind==='failed-after-retry').length};const kindLabel=(kind)=>({permission:vi?'Quyền hạn':'Permission',approval:vi?'Phê duyệt':'Approval','ready-to-review':vi?'Sẵn sàng duyệt':'Ready to review','failed-after-retry':vi?'Thất bại sau khi thử lại':'Failed after retry'}[kind]??String(kind).replaceAll('-',' '));return `<section class="surface-page review-page"><header class="surface-page__header"><div><p class="eyebrow">${vi?'Hộp thư hành động':'Action inbox'}</p><h1>${t('review.title',lang)}</h1><p>${t('review.subtitle',lang)}</p></div><div class="review-summary"><span><strong>${counts.permission+counts.approval}</strong><small>${vi?'cần quyết định':'decisions'}</small></span><span><strong>${counts.review}</strong><small>${vi?'sẵn sàng duyệt':'ready'}</small></span><span data-tone="${counts.failed?'danger':'neutral'}"><strong>${counts.failed}</strong><small>${vi?'bị chặn':'blocked'}</small></span></div></header>${state.status==='loading'?`<div class="page-loading"><span class="spinner"></span>${t('common.loading',lang)}</div>`:state.error?`<div class="page-error">${icon('warning',{size:18})}<span>${esc(state.error)}</span></div>`:queue.length?`<div class="review-list">${queue.map(item=>`<article class="review-item" data-kind="${esc(item.kind)}" data-review-item="${esc(item.id)}"><span class="review-item__icon">${icon(item.kind==='permission'?'shield':item.kind==='failed-after-retry'?'warning':item.kind==='ready-to-review'?'review':'evidence',{size:18})}</span><div><header><strong>${esc(item.title??item.kind)}</strong><span>${esc(kindLabel(item.kind))}</span></header><p>${esc(item.description??item.reason??item.objective??(vi?'Mục này cần bạn quyết định trước khi Nolane tiếp tục.':'This item requires a human decision before Nolane can continue.'))}</p><footer><small>${esc(item.projectId??item.missionId??'')}</small><a href="#/review/${encodeURIComponent(item.missionId??item.id)}" data-route="/review/${encodeURIComponent(item.missionId??item.id)}">${esc(item.primaryAction)} ${icon('arrow',{size:14})}</a></footer></div></article>`).join('')}</div>`:`<div class="empty-state page-empty"><span>${icon('check',{size:20})}</span><strong>${vi?'Mọi thứ đã ổn':'You are all caught up'}</strong><p>${t('review.empty',lang)}</p></div>`}</section>`}
